fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap() // Get the minimum value from the array
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap() // Get the maximum value from the array
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    let n = a.len();
    let mut sorted_a = a.clone(); // Clone the input array to sort it
    sorted_a.sort(); // Sort the array

    if q == 0 {
        return get_min_val(&sorted_a); // Return minimum for 0 quantile
    } else if q == 100 {
        return get_max_val(&sorted_a); // Return maximum for 100 quantile
    }

    // Calculate the index for the quantile
    let index = (q as usize * (n - 1)) / 100; // Calculate the index
    sorted_a[index] // Return the value at the calculated index
}